-- ============================================================================
-- NusaSuite — Sinkronisasi sequence identity SETELAH import data lama.
-- WAJIB dijalankan sekali setiap selesai import (Lihat Langkah 4 panduan).
-- Alasan: kolom GENERATED BY DEFAULT AS IDENTITY tidak maju saat INSERT
-- memakai id eksplisit, jadi nextval() harus dimajukan manual ke MAX(id)+1.
-- Aman diulang (idempoten).
-- ============================================================================

DO $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN SELECT tablename FROM pg_tables WHERE schemaname = 'public' LOOP
    BEGIN
      EXECUTE format(
        'SELECT setval(pg_get_serial_sequence(%L, %L), COALESCE((SELECT MAX(id) FROM %I), 0) + 1, false)',
        r.tablename, 'id', r.tablename);
    EXCEPTION WHEN undefined_table OR undefined_function OR undefined_column THEN
      CONTINUE; -- tabel tanpa kolom id (settings, document_counters, dsb.) dilewati
    END;
  END LOOP;
END $$;

-- Verifikasi manual per tabel bila perlu (ganti nama tabel sesuai kebutuhan):
--   SELECT pg_get_serial_sequence('products', 'id'),
--          (SELECT MAX(id) FROM products), (SELECT last_value FROM products_id_seq);
